const vals = [
['2024-01',158.3],['2024-02',158.8],['2024-03',159.8],['2024-04',160.6],['2024-05',161.5],['2024-06',161.4],['2024-07',162.1],['2024-08',161.8],['2024-09',161.1],['2024-10',161.8],['2024-11',161.8],['2024-12',161.2],['2025-01',161.3],['2025-02',163.0],['2025-03',163.5],['2025-04',163.4],['2025-05',164.3],['2025-06',164.4],['2025-07',164.9],['2025-08',164.8],['2025-09',164.9],['2025-10',165.3],['2025-11',165.4],['2025-12',165.0],['2026-01',165.0],['2026-02',165.9],['2026-03',167.4],['2026-04',168.0],['2026-05',169.6],['2026-06',169.0]
];
const map = new Map(vals);
function yoy(month) { const [y,m]=month.split('-').map(Number); const prev = "'`${y-1}-${String(m).padStart(2,'"'0')}"'`; return 100*(map.get(month)/map.get(prev)-1); }
const yoyRows = vals.slice(12).map(([m])=>[m,+yoy(m).toFixed(3)]);
const latest24 = yoyRows.slice(-18);
const changes = [];
for (let i=1;i<latest24.length;i++) changes.push(latest24[i][1]-latest24[i-1][1]);
const mean = a => a.reduce((s,x)=>s+x,0)/a.length;
const sd = a => { const mu=mean(a); return Math.sqrt(a.reduce((s,x)=>s+(x-mu)**2,0)/(a.length-1)); };
const sorted = [...latest24.map(x=>x[1])].sort((a,b)=>a-b);
function q(a,p){ const pos=(a.length-1)*p; const lo=Math.floor(pos), hi=Math.ceil(pos); return lo===hi?a[lo]:a[lo]+(a[hi]-a[lo])*(pos-lo); }
const last = yoyRows.at(-1)[1];
// seasonal July-Aug cumulative from observed prior years
const cum2024 = map.get('"'2024-08')/map.get('2024-06')-1;
const cum2025 = map.get('2025-08')/map.get('2025-06')-1;
const cumAvg = (cum2024+cum2025)/2;
const augIndex = map.get('2026-06')*(1+cumAvg);
const augYoy = 100*(augIndex/map.get('2025-08')-1);
const sig = sd(changes);
const hw = 1.28*sig;
const cand = {
  schema:'thesis_model_candidate_v1',
  candidates:[
    {model:'last_print_persistence_yoy', point:+last.toFixed(1), p10:+(last-hw).toFixed(1), p50:+last.toFixed(1), p90:+(last+hw).toFixed(1), interval80:[+(last-hw).toFixed(1), +(last+hw).toFixed(1)], interval90:[+(last-1.645*sig).toFixed(1), +(last+1.645*sig).toFixed(1)], interval_method:'successive-yoy-change residual sigma over fetched official history', calibration_n:changes.length, train_cutoff:'2026-06', walk_forward_mae:null},
    {model:'two-year_jul_aug_seasonal_carry_from_index', point:+augYoy.toFixed(1), p10:+(augYoy-hw).toFixed(1), p50:+augYoy.toFixed(1), p90:+(augYoy+hw).toFixed(1), interval80:[+(augYoy-hw).toFixed(1), +(augYoy+hw).toFixed(1)], interval90:[+(augYoy-1.645*sig).toFixed(1), +(augYoy+1.645*sig).toFixed(1)], interval_method:'same residual sigma; point uses 2024 and 2025 Jun-Aug cumulative index moves', calibration_n:changes.length, train_cutoff:'2026-06', walk_forward_mae:null}
  ]
};
console.log(JSON.stringify({
  official_index_excerpt: vals.slice(-18),
  yoyRows,
  latest18_yoy: latest24,
  latest18_stats:{mean:+mean(latest24.map(x=>x[1])).toFixed(3), min:sorted[0], max:sorted.at(-1), q10:+q(sorted,.1).toFixed(3), q90:+q(sorted,.9).toFixed(3)},
  successive_yoy_changes: changes.map(x=>+x.toFixed(3)),
  sigma:+sig.toFixed(3), half_width_1_28_sigma:+hw.toFixed(3),
  june_2026_yoy:+last.toFixed(3), aug2025_index:map.get('2025-08'), jun2026_index:map.get('2026-06'), cum_jun_aug_2024:+(cum2024*100).toFixed(3), cum_jun_aug_2025:+(cum2025*100).toFixed(3), avg_cum:+(cumAvg*100).toFixed(3), implied_aug2026_index:+augIndex.toFixed(3), implied_aug2026_yoy:+augYoy.toFixed(3),
  model_candidates:cand
}, null, 2));
NODE"

